    expect(
      classifyRep({
        isGo: noGoCue.isGo,
        cueShownAt: 1000,
        pressedAt: 900,
        responseWindowMs: config.responseWindowMs,
        hesitationThresholdMs: config.hesitationThresholdMs,
      }),
    ).toEqual({ result: 'false_start', reactionMs: null, score: -1 })
  })

