/* ---- HUD ---- */
.hud-clock,
.hud-penalties {
  font-family: ui-monospace, monospace;
  color: var(--gym-fg);
  font-size: 1.1rem;
  padding: 0.2rem 0.55rem;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.05);
}
.hud-penalties {
  color: var(--gym-warn);
  font-weight: 700;
}

/* ---- Rest screen ---- */
.screen.rest {
  position: relative;
  background: #0b1220;
}
.screen.rest .stage {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 1.5rem;
}
.screen.rest h2 {
  font-size: clamp(3rem, 8vw, 6rem);
  letter-spacing: 8px;
