  color: var(--gym-accent);
  line-height: 1;
}
.penalty-panel {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 0.75rem;
  background: var(--gym-neutral);
  padding: 1.4rem 2rem;
  border-radius: 12px;
}
.penalty-count {
  font-size: 1.4rem;
  font-weight: 700;
  margin: 0;
}
.muted {
  color: var(--gym-muted);
  margin: 0;
}

/* ---- Settings screen ---- */
.screen.settings {
  align-items: stretch;
  max-width: 720px;
  margin: 0 auto;
  width: 100%;
  gap: 1.2rem;
}
.settings-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.settings-header h1 {
  margin: 0;
  font-size: 1.8rem;
}
.settings-section {
  background: var(--gym-neutral);
  padding: 1rem 1.2rem;
  border-radius: 10px;
  display: flex;
  flex-direction: column;
  gap: 0.7rem;
}
.settings-section h2 {
  margin: 0;
  font-size: 1rem;
  text-transform: uppercase;
  letter-spacing: 1px;
  color: var(--gym-muted);
