import { getDb } from './db'
import { DEFAULT_SETTINGS, type SettingsRecord } from './settings-types'
import {
  buildDefaultProfile,
  ensureAtLeastOneProfile,
  getProfile,
  listProfiles,
  saveProfile,
  type ProfileRecord,
} from './profiles'
import type { DrillConfig } from '../engine/types'

export { DEFAULT_SETTINGS, type SettingsRecord } from './settings-types'

export async function loadSettings(): Promise<SettingsRecord> {
  const db = getDb()
  if (!db) return DEFAULT_SETTINGS
  try {
    const row = await db.settings.get('singleton')
    if (!row) return DEFAULT_SETTINGS
    return { ...DEFAULT_SETTINGS, ...row }
  } catch {
    return DEFAULT_SETTINGS
  }
}

export async function saveSettings(s: SettingsRecord): Promise<void> {
  const db = getDb()
  if (!db) return
  try {
    await db.settings.put(s)
  } catch {
    /* ignore */
  }
}

/**
 * Resolve the user's active drill profile. On first run (or after migrating
 * from Phase 2/3) seeds a Default profile from whatever DrillConfig-shaped
 * fields the SettingsRecord carries, then persists `activeProfileId`.
 */
export async function loadActiveProfile(): Promise<ProfileRecord> {
  const settings = await loadSettings()
  if (settings.activeProfileId) {
    const existing = await getProfile(settings.activeProfileId)
    if (existing) return existing
  }
  // Migration / first run: seed from current settings drill fields.
  const overrides: Partial<DrillConfig> = {
    preCueMinMs: settings.preCueMinMs,
    preCueMaxMs: settings.preCueMaxMs,
    rounds: settings.rounds,
    workMs: settings.workMs,
    restMs: settings.restMs,
    penaltyCounterEnabled: settings.penaltyCounterEnabled,
    perFalseStartPenalty: settings.perFalseStartPenalty,
    perHesitationPenalty: settings.perHesitationPenalty,
    distanceAxisEnabled: settings.distanceAxisEnabled,
    audioToneEnabled: settings.audioToneEnabled,
    textOverlayEnabled: settings.textOverlayEnabled,
  }
  const existing = await listProfiles()
  if (existing.length > 0) {
    await saveSettings({ ...settings, activeProfileId: existing[0].id })
    return existing[0]
  }
  const seed = buildDefaultProfile(overrides)
  await saveProfile(seed)
  await saveSettings({ ...settings, activeProfileId: seed.id })
  return seed
}

export async function setActiveProfile(id: string): Promise<void> {
  const settings = await loadSettings()
  await saveSettings({ ...settings, activeProfileId: id })
}

export { ensureAtLeastOneProfile }

