import { chromium } from 'playwright';
import { mkdirSync } from 'node:fs';
import { resolve } from 'node:path';

const OUT = resolve('/home/aaron/dev/projects/aaron/pointfight-reactor/artifacts/phase4-reverify');
mkdirSync(OUT, { recursive: true });

const consoleErrors = [];
const allConsole = [];

function attachConsole(page, label) {
  page.on('console', (msg) => {
    const text = `[${label}] ${msg.type()}: ${msg.text()}`;
    allConsole.push(text);
    if (msg.type() === 'error') consoleErrors.push(text);
  });
  page.on('pageerror', (err) => {
    const text = `[${label}] pageerror: ${err.message}`;
    allConsole.push(text);
    consoleErrors.push(text);
  });
}

async function clearIDB(page) {
  await page.evaluate(async () => {
    await new Promise((res, rej) => {
      const req = indexedDB.deleteDatabase('pointfight-reactor');
      req.onsuccess = () => res();
      req.onerror = () => rej(req.error);
      req.onblocked = () => res();
    });
  });
}

async function main() {
  const browser = await chromium.launch();
  const ctx = await browser.newContext();
  const page = await ctx.newPage();
  attachConsole(page, 'main');

  const results = {};

  // ====================== Defect 1 ======================
  // First load to register the SW/IDB
  await page.goto('http://localhost:5177/', { waitUntil: 'networkidle' });
  await page.waitForTimeout(500);

  // Clear IDB
  await clearIDB(page);
  // Hard reload
  await page.reload({ waitUntil: 'networkidle' });
  await page.waitForTimeout(800);

  await page.screenshot({ path: `${OUT}/01-idle-after-clear.png`, fullPage: true });

  // Open Settings
  const settingsBtn = page.getByRole('button', { name: /settings/i }).first();
  await settingsBtn.click();
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${OUT}/02-settings-open.png`, fullPage: true });

  // Find select for Active profile and count "Default" entries
  const selects = await page.locator('select').all();
  let defaultCount = -1;
  let allOptions = [];
  for (const sel of selects) {
    const opts = await sel.locator('option').allTextContents();
    allOptions.push(opts);
    const c = opts.filter((t) => t.trim() === 'Default').length;
    if (c > 0) defaultCount = c;
  }
  results.defect1 = {
    defaultCount,
    allOptions,
    pass: defaultCount === 1,
  };

  // ====================== Defect 2 ======================
  // Already on Settings. Create new profile "Sparring".
  // Look for a button/input to create profile.
  const newNameInput = page.locator('input[type="text"]').first();
  await newNameInput.fill('Sparring');
  await page.screenshot({ path: `${OUT}/03-sparring-typed.png`, fullPage: true });

  const createBtn = page.getByRole('button', { name: /create|new profile|add/i }).first();
  await createBtn.click();
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${OUT}/04-after-create.png`, fullPage: true });

  // Close settings - find a "Close" or "Back" or "Done" button. Try a few.
  const closeCandidates = [/done/i, /close/i, /back/i, /save/i];
  let closed = false;
  for (const re of closeCandidates) {
    const btn = page.getByRole('button', { name: re });
    if ((await btn.count()) > 0) {
      await btn.first().click();
      closed = true;
      break;
    }
  }
  await page.waitForTimeout(500);
  await page.screenshot({ path: `${OUT}/05-after-close-settings.png`, fullPage: true });

  // Check idle shows "Profile: Sparring"
  const idleTextAfterCreate = await page.locator('body').innerText();
  const showsSparring = /Profile:\s*Sparring/i.test(idleTextAfterCreate);
  results.defect2_step2_showsSparring = showsSparring;

  // Open settings again
  await page.getByRole('button', { name: /settings/i }).first().click();
  await page.waitForTimeout(400);
  await page.screenshot({ path: `${OUT}/06-settings-reopened.png`, fullPage: true });

  // Switch dropdown to Default
  const profileSelect = page.locator('select').first();
  await profileSelect.selectOption({ label: 'Default' });
  await page.waitForTimeout(300);
  await page.screenshot({ path: `${OUT}/07-selected-default.png`, fullPage: true });

  // Click Save
  const saveBtn = page.getByRole('button', { name: /save/i }).first();
  await saveBtn.click();
  await page.waitForTimeout(600);
  await page.screenshot({ path: `${OUT}/08-after-save.png`, fullPage: true });

  // Now on idle screen, check it shows Profile: Default
  const idleAfterSwitch = await page.locator('body').innerText();
  const showsDefault = /Profile:\s*Default/i.test(idleAfterSwitch);
  const stillSparring = /Profile:\s*Sparring/i.test(idleAfterSwitch);
  results.defect2 = {
    showsDefault,
    stillSparring,
    idleSample: idleAfterSwitch.slice(0, 600),
    pass: showsDefault && !stillSparring,
  };

  // ====================== Bonus regression ======================
  // Settings opens without errors - already done. New profile creation works (Sparring exists).
  // Run a tiny drill to check Summary "Rhythm pattern" renders.
  // Find the Start button (might be on idle).
  await page.screenshot({ path: `${OUT}/09-before-drill.png`, fullPage: true });
  const startBtn = page.getByRole('button', { name: /^start/i }).first();
