  const stillSparring = /Profile:\s*Sparring/i.test(idleAfterSwitch);
  results.defect2 = {
    showsDefault,
    stillSparring,
    idleSample: idleAfterSwitch.slice(0, 600),
    pass: showsDefault && !stillSparring,
  };

